struct Shallow {
    int* data;
};

Shallow a{new int(5)};
Shallow b = a;      // copies the address

*b.data = 9;        // a sees 9 too!

struct Deep {
    int* data;
    Deep(int v) : data(new int(v)) {}
    Deep(const Deep& o)
        : data(new int(*o.data)) {}  // new block
    ~Deep() { delete data; }
};

Deep a(5);
Deep b = a;         // copies the value

*b.data = 9;        // a is still 5
